print(f"🚀 KEMPLE Simülasyonu Başlıyor! Toplam {len(rows)} ihbar sisteme basılıyor...")

url = 'http://localhost:3001/api/packet'

for i, row in enumerate(rows):
    id_num, payload_text, persons, score, severity, note = row
    
    # Erzurum koordinatları etrafında
    lat = 39.90 + random.uniform(-0.05, 0.05)
    lng = 41.27 + random.uniform(-0.05, 0.05)
    
    data = {
        "packet_uuid": str(uuid.uuid4()),
        "device_id": f"dataset-sim-{id_num}",
        "payload": payload_text,
        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "origin_location": {"lat": lat, "lng": lng},
        "last_seen_location": {"lat": lat, "lng": lng},
        "schema_version": "1.0",
        "iteration_count": 0
    }
    
    req = urllib.request.Request(url, data=json.dumps(data).encode('utf-8'), headers={'Content-Type': 'application/json'})
    
    try:
        response = urllib.request.urlopen(req)
        print(f"[{i+1}/{len(rows)}] ✅ {severity} Risk: {payload_text[:40]}...")
    except Exception as e:
        print(f"[{i+1}/{len(rows)}] ❌ Hata: {e}")
        
    time.sleep(0.3)

print("✅ Tüm 300 senaryo başarıyla sisteme aktarıldı!")
